INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(450, 'cache', '/kæʃ/', 'noun', '{"zh-TW":["快取"],"en":["stored data for quick access"]}', NULL, 'clear cache / cache memory', '[{"en":"Clear the cache to fix the issue.","zh-TW":"清除快取來解決問題。"},{"en":"The browser stores data in the cache.","zh-TW":"瀏覽器將資料存在快取中。"}]', NULL, NULL, 2, 450, NULL),
(451, 'cafeteria', '/ˌkæfɪˈtɪəriə/', 'noun', '{"zh-TW":["自助餐廳；食堂"],"en":["a restaurant where customers serve themselves"]}', NULL, 'school cafeteria / office cafeteria', '[{"en":"The company cafeteria offers a variety of healthy meals.","zh-TW":"公司食堂提供各種健康餐食。"},{"en":"Students eat lunch in the school cafeteria.","zh-TW":"學生在學校食堂吃午餐。"}]', NULL, NULL, 3, 451, NULL),
(452, 'cage', '/keɪdʒ/', 'noun', '{"zh-TW":["籠子"],"en":["a structure of bars for keeping animals"]}', NULL, 'bird cage / cage match', '[{"en":"The bird escaped from its cage.","zh-TW":"鳥從籠子裡逃了出來。"},{"en":"The lion paced in its cage.","zh-TW":"獅子在籠子裡踱步。"}]', '{"verb":"cage","adjective":"caged"}', NULL, 1, 452, NULL),
(453, 'cake', '/keɪk/', 'noun', '{"zh-TW":["蛋糕"],"en":["a sweet baked food"]}', NULL, 'piece of cake / birthday cake', '[{"en":"Would you like some cake?","zh-TW":"你想要一些蛋糕嗎？"},{"en":"That test was a piece of cake.","zh-TW":"那個考試太容易了。"}]', NULL, NULL, 1, 453, NULL),
(454, 'calculate', '/ˈkælkjʊleɪt/', 'verb', '{"zh-TW":["計算；估算","計算"],"en":["to determine by mathematical process","to determine by mathematical methods"]}', '{"root":{"text":"calcul","meaning":"pebble/count (石子/計數)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"用石子計數，即「計算」。"}', 'calculate costs/risk/profit; calculate the cost / carefully calculated', '[{"en":"We need to calculate the total project cost.","zh-TW":"我們需要計算專案總成本。"},{"en":"The software calculates tax automatically.","zh-TW":"軟體會自動計算稅金。"},{"en":"Can you calculate the total cost?","zh-TW":"你能計算總費用嗎？"},{"en":"The risk was carefully calculated.","zh-TW":"風險經過仔細計算。"}]', '{"noun":"calculation","noun2":"calculator"}', NULL, 3, 454, NULL),
(455, 'calculation', 'ˌkælkjʊˈleɪʃən', 'noun', '{"zh-TW":["計算；估算","推算"],"en":["a mathematical process","a careful estimate"]}', NULL, 'rough calculation/final calculation', '[{"en":"Please double-check the calculation.","zh-TW":"請仔細核對計算結果。"}]', '{"verb":"calculate","adjective":"calculated","adverb":"calculatedly"}', NULL, 4, 455, 518),
(456, 'call', '/kɔːl/', 'verb', '{"zh-TW":["打電話；稱呼"],"en":["to telephone","to give a name to"]}', NULL, 'call back / conference call', '[{"en":"I will call you back in five minutes.","zh-TW":"我五分鐘後回電給你。"},{"en":"We have a conference call at 3 p.m.","zh-TW":"我們下午3點有一通電話會議。"}]', '{"verb":"call","noun":"call","noun2":"caller"}', NULL, 1, 456, NULL),
(457, 'callable', '/ˈkɔːləbəl/', 'adjective', '{"zh-TW":["可贖回的；可召回的"],"en":["able to be redeemed or called by the issuer before maturity"]}', NULL, 'callable bond / callable loan', '[{"en":"Callable bonds give the issuer the option to repay early.","zh-TW":"可贖回債券賦予發行者提前還款的選擇權。"},{"en":"The callable feature reduces yield for investors.","zh-TW":"可贖回特徵降低了投資者的收益率。"}]', NULL, NULL, 3, 457, NULL),
(458, 'callback', '/ˈkɔːlbæk/', 'noun', '{"zh-TW":["回電；回撥"],"en":["a phone call made in response to a missed call or request"]}', NULL, 'request a callback / schedule a callback', '[{"en":"Please leave your number and we will arrange a callback.","zh-TW":"請留下您的電話，我們將安排回電。"},{"en":"The customer requested a callback within the hour.","zh-TW":"顧客要求在一小時內回電。"}]', '{"verb":"call back"}', NULL, 3, 458, NULL),
(459, 'calm', '/kɑːm/', 'adjective', '{"zh-TW":["平靜的；冷靜的"],"en":["not excited or upset; peaceful","not showing or feeling nervousness or anger"]}', '{"root":{"text":"calm","meaning":"still/quiet (靜止)"},"logic":"源自希臘語 kauma（炎熱中的休息），指平靜狀態。"}', 'stay calm / calm down; stay calm / calm down / calm and collected', '[{"en":"Please stay calm during the evacuation.","zh-TW":"疏散時請保持冷靜。"},{"en":"The manager remained calm under pressure.","zh-TW":"經理在壓力下保持冷靜。"},{"en":"Please stay calm during the emergency.","zh-TW":"緊急情況時請保持冷靜。"},{"en":"The sea was perfectly calm that morning.","zh-TW":"那天早上海面非常平靜。"}]', '{"adjective":"calm","verb":"calm","noun":"calmness","adverb":"calmly"}', NULL, 1, 459, NULL),
(460, 'camera', '/ˈkæmərə/', 'noun', '{"zh-TW":["相機"],"en":["a device for taking photographs"]}', NULL, 'security camera / camera angle', '[{"en":"I forgot my camera at home.","zh-TW":"我把相機忘在家裡了。"},{"en":"The store has security cameras.","zh-TW":"商店裝有監視器。"}]', NULL, NULL, 2, 460, NULL),
(461, 'camp', '/kæmp/', 'noun', '{"zh-TW":["營地；露營"],"en":["a place with tents for staying outdoors"]}', NULL, 'summer camp / camp out', '[{"en":"The kids went to summer camp.","zh-TW":"孩子們去了夏令營。"},{"en":"We camped by the lake.","zh-TW":"我們在湖邊露營。"}]', '{"verb":"camp","noun2":"camping","noun3":"campsite"}', NULL, 1, 461, NULL),
(462, 'campaign', '/kæmˈpeɪn/', 'noun', '{"zh-TW":["活動；運動","宣傳","競選活動；運動","活動；競選"],"en":["an organized course of action to achieve a goal","organized activities to achieve a goal"]}', '{"root":{"text":"camp","meaning":"field (原野)"},"suffix":{"text":"-aign","meaning":"action (行動)"},"logic":"在原野上的行動，即「活動」。"}', 'marketing campaign / advertising campaign / launch a campaign; election campaign / advertising campaign; advertising campaign / election campaign / launch a campaign', '[{"en":"The marketing campaign generated significant leads.","zh-TW":"行銷活動產生了大量潛在客戶。"},{"en":"They launched a campaign to promote sustainability.","zh-TW":"他們發起了促進永續發展的活動。"},{"en":"The campaign starts next month.","zh-TW":"競選活動下個月開始。"},{"en":"They launched a campaign against smoking.","zh-TW":"他們發起了反菸運動。"},{"en":"The company launched a new marketing campaign.","zh-TW":"公司發起了新的行銷活動。"},{"en":"She is running a campaign for mayor.","zh-TW":"她正在競選市長。"}]', '{"verb":"campaign","noun2":"campaigner"}', NULL, 3, 462, NULL),
(463, 'campus', '/ˈkæmpəs/', 'noun', '{"zh-TW":["校園"],"en":["the grounds of a university or college"]}', NULL, 'on campus / campus life', '[{"en":"The university has a beautiful campus.","zh-TW":"這所大學有一個美麗的校園。"},{"en":"Students live on campus.","zh-TW":"學生住在校園裡。"}]', NULL, NULL, 2, 463, NULL),
(464, 'cancel', 'ˈkænsəl', 'verb', '{"zh-TW":["取消；撤銷","刪除"],"en":["to stop a planned event","to end an agreement"]}', NULL, 'cancel a meeting/cancel an order', '[{"en":"The meeting was cancelled due to the storm.","zh-TW":"由於暴風雨，會議被取消了。"}]', '{"noun":"cancellation","adjective":"cancelled"}', NULL, 2, 464, 14),
(465, 'cancellation', '/ˌkænsəˈleɪʃən/', 'noun', '{"zh-TW":["取消"],"en":["the action of cancelling a scheduled event"]}', NULL, 'flight cancellation / hotel cancellation', '[{"en":"The cancellation of the flight caused major delays.","zh-TW":"班機取消導致嚴重延誤。"},{"en":"We received a cancellation notice this morning.","zh-TW":"我們今天早上收到了取消通知。"}]', '{"verb":"cancel","adjective":"cancelled"}', NULL, 4, 465, NULL),
(466, 'candidate', '/ˈkændɪdət/', 'noun', '{"zh-TW":["候選人；應徵者"],"en":["a person who applies for a job or is nominated for a position"]}', '{"root":{"text":"candid","meaning":"white (白色)"},"suffix":{"text":"-ate","meaning":"person (人)"},"logic":"穿白袍的人（古羅馬參選者），即「候選人」。"}', 'ideal candidate / qualified candidate / shortlist candidates', '[{"en":"We interviewed five candidates for the position.","zh-TW":"我們面試了五位候選人。"},{"en":"The ideal candidate should have 5+ years of experience.","zh-TW":"理想候選人應有5年以上經驗。"}]', '{"noun":"candidacy"}', NULL, 3, 466, 15),
(467, 'canvas', '/ˈkænvəs/', 'noun', '{"zh-TW":["畫布"],"en":["a strong cloth used for painting on"]}', '{"root":{"text":"canvas","meaning":"hemp cloth (麻布)"},"logic":"源自拉丁語 cannabis（大麻），原指麻布。"}', 'oil on canvas / blank canvas', '[{"en":"The artist stretched a new canvas.","zh-TW":"藝術家繃上一塊新畫布。"},{"en":"The painting is oil on canvas.","zh-TW":"這幅畫是油畫。"}]', NULL, NULL, 2, 467, NULL),
(468, 'cap', '/kæp/', 'noun', '{"zh-TW":["帽子；蓋子"],"en":["a type of soft hat; a covering for a bottle"]}', NULL, 'baseball cap / cap off', '[{"en":"He always wears a baseball cap.","zh-TW":"他總是戴著棒球帽。"},{"en":"Put the cap back on the bottle.","zh-TW":"把瓶蓋蓋回去。"}]', NULL, NULL, 1, 468, NULL),
(469, 'capable', '/ˈkeɪpəbl/', 'adjective', '{"zh-TW":["有能力的"],"en":["having the ability or quality to do something","having the ability to do something"]}', '{"root":{"text":"cap","meaning":"take/hold (拿/容納)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠容納的，即「有能力的」。"}', 'capable of / highly capable', '[{"en":"She is capable of managing large-scale projects.","zh-TW":"她有能力管理大型專案。"},{"en":"We need a capable leader for this division.","zh-TW":"我們需要一位有能力的人來領導這個部門。"},{"en":"She is capable of handling the task alone.","zh-TW":"她有能力獨自處理這項任務。"},{"en":"He is a highly capable manager.","zh-TW":"他是一位非常能幹的經理。"}]', '{"noun":"capability"}', NULL, 3, 469, 281),
(470, 'capacity', '/kəˈpæsəti/', 'noun', '{"zh-TW":["容量；能力","身份"],"en":["the maximum amount that can be contained","the ability or power to do something"]}', '{"root":{"text":"cap","meaning":"hold (容納)"},"suffix":{"text":"-acity","meaning":"state of (狀態)"},"logic":"能容納的狀態，即「容量」。"}', 'full capacity / production capacity / in the capacity of', '[{"en":"The factory is operating at full capacity.","zh-TW":"工廠正以滿產能運作。"},{"en":"He served in the capacity of financial advisor.","zh-TW":"他以財務顧問的身份服務。"}]', NULL, NULL, 3, 470, 78),
(471, 'capex', '/ˈkeɪpeks/', 'noun', '{"zh-TW":["資本支出（縮寫）"],"en":["short for capital expenditure; funds used to acquire long-term assets"]}', NULL, 'reduce capex / capex budget / heavy capex', '[{"en":"The company cut capex to preserve cash during the downturn.","zh-TW":"公司在低迷期間削減資本支出以保存現金。"},{"en":"High capex requirements make the industry a barrier to new entrants.","zh-TW":"高資本支出要求使該行業對新進入者形成壁壘。"}]', NULL, NULL, 2, 471, NULL),
(472, 'capital', '/ˈkæpɪtl/', 'noun', '{"zh-TW":["【主要意義-名詞】首都；資本金","【次要意義-形容詞】大寫的（字母）","【次要意義-形容詞】死刑的（capital punishment = 死刑）","【次要意義-名詞】資本；資金"],"en":["[primary - noun] the most important city in a country; funds for investment","[secondary - adjective] relating to uppercase letters","[secondary - adjective] involving the death penalty","[secondary - noun] wealth used to generate income"]}', '{"root":{"text":"capit","meaning":"head (頭)"},"suffix":{"text":"-al","meaning":"relating to (有關的)"},"logic":"頭部（最重要的），即「首都、資本」。"}', 'capital punishment / capital gain / capital letter / venture capital / capital expenditure', '[{"en":"The company raised additional capital through a public stock offering.","zh-TW":"公司通過公開股票發行籌集了額外資本。"},{"en":"Capital expenditure on new equipment increased by 20 percent this year.","zh-TW":"今年新設備的資本支出增加了20%。"},{"en":"All company names must be written with a capital letter.","zh-TW":"所有公司名稱必須以大寫字母書寫。"}]', '{"verb":"capitalize","adjective":"capitalist"}', 'capital 的次要意義包括「大寫的」（capital letter）、「死刑的」（capital punishment）和「資本的」（capital gain/expenditure），TOEIC 財務文章中 capital expenditure 和 capital gain 是必考搭配。', 3, 472, 520),
(473, 'capitalization', '/ˌkæpɪtəlaɪˈzeɪʃən/', 'noun', '{"zh-TW":["資本化；市值"],"en":["the total value of a company''s outstanding shares; also the process of recording an expense as an asset"]}', NULL, 'market capitalization / large cap / small cap', '[{"en":"The company''s market capitalization exceeded one billion dollars.","zh-TW":"公司市值超過了十億美元。"},{"en":"Software development costs were capitalized rather than expensed.","zh-TW":"軟體開發成本被資本化而非費用化處理。"}]', '{"verb":"capitalize","adjective":"capitalized"}', NULL, 5, 473, 756),
(474, 'capitalize', '/ˈkæpɪtəlaɪz/', 'verb', '{"zh-TW":["利用；資本化"],"en":["to take advantage of an opportunity","to provide with capital"]}', '{"root":{"text":"capital","meaning":"capital (資本)"},"suffix":{"text":"-ize","meaning":"to make (使)"},"logic":"使成為資本（利用資源），即「利用」。"}', 'capitalize on opportunity / capitalize assets', '[{"en":"We must capitalize on this market opportunity.","zh-TW":"我們必須利用這個市場機會。"},{"en":"The startup needs to capitalize its operations.","zh-TW":"這家新創公司需要為營運提供資金。"}]', '{"noun":"capitalization"}', NULL, 4, 474, 651),
(475, 'captain', '/ˈkæptɪn/', 'noun', '{"zh-TW":["隊長；船長"],"en":["the leader of a team or ship"]}', NULL, 'team captain / captain of industry', '[{"en":"She is the team captain.","zh-TW":"她是隊長。"},{"en":"The captain steered the ship safely.","zh-TW":"船長安全地駕駛了船。"}]', NULL, NULL, 3, 475, NULL),
(476, 'capture', '/ˈkæptʃər/', 'verb', '{"zh-TW":["捕獲；佔領","吸引","捕獲；捕捉"],"en":["to take control or possession of","to attract and hold attention","to catch a person or animal"]}', '{"root":{"text":"capt","meaning":"take/seize (抓取)"},"suffix":{"text":"-ure","meaning":"action (動作)"},"logic":"抓取的動作，即「捕獲」。"}', 'capture market share / capture attention / capture data; capture attention / capture the moment', '[{"en":"The company captured 30% of the market share.","zh-TW":"公司佔據了30%的市場份額。"},{"en":"The presentation captured everyone''s attention.","zh-TW":"簡報吸引了所有人的注意力。"},{"en":"The photo captured the moment perfectly.","zh-TW":"這張照片完美地捕捉了那一刻。"},{"en":"The criminal was captured by police.","zh-TW":"罪犯被警察逮捕了。"}]', '{"noun":"capture"}', NULL, 3, 476, NULL),
(477, 'car', '/kɑːr/', 'noun', '{"zh-TW":["汽車"],"en":["a motor vehicle for passengers","a road vehicle with an engine"]}', NULL, 'by car / car park', '[{"en":"She drives to work by car.","zh-TW":"她開車上班。"},{"en":"The car park is behind the building.","zh-TW":"停車場在大樓後面。"},{"en":"I need to fix my car.","zh-TW":"我需要修理我的車。"}]', '{"noun":"car"}', NULL, 1, 477, NULL),
(478, 'carbon', '/ˈkɑːrbən/', 'noun', '{"zh-TW":["碳"],"en":["a chemical element found in all living things"]}', '{"root":{"text":"carbon","meaning":"coal (�ite)"},"logic":"源自拉丁語 carbo（煤炭）。"}', 'carbon dioxide / carbon footprint / carbon emissions', '[{"en":"Trees absorb carbon dioxide from the atmosphere.","zh-TW":"樹木從大氣中吸收二氧化碳。"},{"en":"We should reduce our carbon footprint.","zh-TW":"我們應該減少碳足跡。"}]', NULL, NULL, 2, 478, NULL),
(479, 'card', '/kɑːrd/', 'noun', '{"zh-TW":["卡片；紙牌"],"en":["a piece of stiff paper; a credit card"]}', NULL, 'credit card / playing cards', '[{"en":"Can I pay by card?","zh-TW":"我可以刷卡嗎？"},{"en":"She sent me a birthday card.","zh-TW":"她寄了一張生日卡給我。"}]', NULL, NULL, 1, 479, NULL),
(480, 'cardiology', '/ˌkɑːrdiˈɒlədʒi/', 'noun', '{"zh-TW":["心臟病學；心臟科"],"en":["the branch of medicine dealing with heart disorders"]}', NULL, 'cardiology department / consult a cardiologist', '[{"en":"She was referred to the cardiology department for tests.","zh-TW":"她被轉介到心臟科進行檢查。"},{"en":"Advances in cardiology have saved millions of lives.","zh-TW":"心臟病學的進步挽救了數百萬生命。"}]', '{"noun":"cardiologist","adjective":"cardiac"}', NULL, 4, 480, NULL),
(481, 'career', '/kəˈrɪər/', 'noun', '{"zh-TW":["職業；職涯"],"en":["an occupation undertaken for a significant period of one''s life"]}', '{"root":{"text":"carr","meaning":"road/vehicle (路/車)"},"suffix":{"text":"-eer","meaning":"person engaged in (從事…的人)"},"logic":"人生道路上從事的，即「職業」。"}', 'career development / career path / career change', '[{"en":"She made a career change from finance to tech.","zh-TW":"她從金融轉職到科技業。"},{"en":"The company offers excellent career development opportunities.","zh-TW":"公司提供優秀的職涯發展機會。"}]', NULL, NULL, 2, 481, NULL),
(482, 'careful', '/ˈkɛərfəl/', 'adjective', '{"zh-TW":["小心的；仔細的"],"en":["giving attention to avoid mistakes or danger","giving attention to avoid danger or mistakes"]}', NULL, 'be careful / careful planning; be careful / careful with', '[{"en":"Be careful with the fragile items.","zh-TW":"小心處理易碎物品。"},{"en":"Careful planning led to success.","zh-TW":"仔細的規劃帶來了成功。"},{"en":"Be careful crossing the road.","zh-TW":"過馬路要小心。"},{"en":"She''s very careful with money.","zh-TW":"她花錢很謹慎。"}]', '{"adjective":"careful","adverb":"carefully","noun":"care","adjective2":"careless"}', NULL, 3, 482, NULL),
(483, 'cargo', '/ˈkɑːrɡəʊ/', 'noun', '{"zh-TW":["貨物"],"en":["goods carried by a vehicle, ship, or aircraft"]}', '{"root":{"text":"carg","meaning":"load (裝載)"},"suffix":{"text":"-o","meaning":"noun ending (名詞字尾)"},"logic":"裝載的東西，即「貨物」。"}', 'cargo ship / air cargo / cargo container', '[{"en":"The cargo was damaged during transit.","zh-TW":"貨物在運輸過程中受損。"},{"en":"Air cargo rates have increased significantly.","zh-TW":"空運費率大幅上漲。"}]', NULL, NULL, 2, 483, 833),
(484, 'carry', '/ˈkæri/', 'verb', '{"zh-TW":["攜帶；執行","承擔"],"en":["to transport or convey","to support the weight of"]}', '{"root":{"text":"carry","meaning":"transport (運送)"},"logic":"運送，即「攜帶」。"}', 'carry out / carry on / carry risk', '[{"en":"The team will carry out the plan next quarter.","zh-TW":"團隊將在下季度執行計畫。"},{"en":"All investments carry some degree of risk.","zh-TW":"所有投資都帶有一定程度的風險。"}]', '{"noun":"carrier"}', NULL, 2, 484, NULL),
(485, 'carry-forward', '/ˈkæri ˈfɔːrwərd/', 'noun', '{"zh-TW":["結轉"],"en":["the transfer of an unused amount to a future accounting period"]}', NULL, 'loss carry-forward / tax loss carry-forward', '[{"en":"The company used a tax loss carry-forward to offset future taxable income.","zh-TW":"公司使用稅損結轉來抵消未來的應稅收入。"},{"en":"A carry-forward of unused annual leave must be taken within 12 months.","zh-TW":"未使用年假的結轉必須在12個月內使用。"}]', '{"verb":"carry forward"}', NULL, 5, 485, NULL),
(486, 'carry-on', '/ˈkæri ɒn/', 'noun', '{"zh-TW":["手提行李"],"en":["a bag small enough to be taken on a plane"]}', NULL, 'carry-on bag / carry-on limit', '[{"en":"Each passenger is allowed one carry-on bag.","zh-TW":"每位乘客可攜帶一件手提行李。"},{"en":"Your carry-on must fit in the overhead bin.","zh-TW":"您的手提行李必須放得進頭頂置物箱。"}]', NULL, NULL, 3, 486, NULL),
(487, 'cart', '/kɑːrt/', 'noun', '{"zh-TW":["購物車；手推車"],"en":["a vehicle with wheels used for carrying goods"]}', '{"root":{"text":"cart","meaning":"vehicle (車)"},"logic":"源自古英語 cræt（車），指用於搬運的推車。"}', 'shopping cart / add to cart', '[{"en":"Please put the items in the cart.","zh-TW":"請把商品放進購物車。"},{"en":"She added three items to her online cart.","zh-TW":"她在網路購物車中加了三樣商品。"}]', '{"verb":"cart"}', NULL, 1, 487, NULL),
(488, 'cartel', '/kɑːrˈtel/', 'noun', '{"zh-TW":["卡特爾；聯合壟斷"],"en":["a group of companies cooperating illegally to fix prices or output"]}', NULL, 'form a cartel / price-fixing cartel / cartel investigation', '[{"en":"The antitrust authority broke up the cartel for price fixing.","zh-TW":"反壟斷機構因操縱價格而解散了卡特爾。"},{"en":"OPEC is often described as an oil production cartel.","zh-TW":"OPEC常被描述為石油生產卡特爾。"}]', NULL, NULL, 2, 488, NULL),
(489, 'carve', '/kɑːrv/', 'verb', '{"zh-TW":["雕刻"],"en":["to cut a hard material to produce a shape"]}', '{"root":{"text":"carve","meaning":"cut (切割)"},"logic":"源自古英語 ceorfan（切割）。"}', 'carve a statue / carve wood / carve out', '[{"en":"He carved a beautiful figure from wood.","zh-TW":"他用木頭雕刻了一個美麗的人像。"},{"en":"The sculptor carved the marble with great skill.","zh-TW":"雕塑家以高超技藝雕刻大理石。"}]', '{"noun":"carving","noun2":"carver"}', NULL, 2, 489, NULL),
(490, 'carve-out', '/ˈkɑːrvaʊt/', 'noun', '{"zh-TW":["剝離；分拆"],"en":["separating a business unit into a separate entity or sale"]}', NULL, 'complete a carve-out / carve-out strategy', '[{"en":"The carve-out of the logistics division raised 200 million.","zh-TW":"物流部門的剝離籌集了2億元。"},{"en":"A carve-out allows focus on the core business while monetizing assets.","zh-TW":"剝離允許專注於核心業務同時實現資產變現。"}]', NULL, NULL, 3, 490, NULL),
(491, 'cashback', '/ˈkæʃbæk/', 'noun', '{"zh-TW":["現金回饋"],"en":["a reward scheme where a portion of spending is returned to the buyer"]}', NULL, 'cashback offer / earn cashback / cashback card / cashback program', '[{"en":"The credit card offers 2% cashback on all purchases.","zh-TW":"信用卡對所有購買提供2%的現金回饋。"},{"en":"Cashback incentives increased average transaction size.","zh-TW":"現金回饋激勵增加了平均交易金額。"}]', NULL, NULL, 3, 491, NULL),
(492, 'cashier', '/kæˈʃɪr/', 'noun', '{"zh-TW":["收銀員"],"en":["a person who handles payments in a store"]}', '{"root":{"text":"cash","meaning":"money (現金)"},"suffix":{"text":"-ier","meaning":"person who (從事…的人)"},"logic":"處理現金的人，即「收銀員」。"}', 'cashier counter / head cashier', '[{"en":"The cashier scanned all the items.","zh-TW":"收銀員掃描了所有商品。"},{"en":"Please pay the cashier at the front.","zh-TW":"請到前面的收銀台付款。"}]', '{"noun":"cash"}', NULL, 3, 492, NULL),
(493, 'casual', '/ˈkæʒuəl/', 'adjective', '{"zh-TW":["休閒的；隨意的"],"en":["relaxed and unconcerned","not formal"]}', '{"root":{"text":"cas","meaning":"fall/chance (偶然)"},"suffix":{"text":"-ual","meaning":"relating to (相關的)"},"logic":"與偶然相關的，指不正式的、隨意的。"}', 'casual clothes / casual conversation / casual worker', '[{"en":"The dress code is casual on Fridays.","zh-TW":"週五的穿著規定是休閒服。"},{"en":"It was just a casual remark.","zh-TW":"那只是一句隨口說說。"}]', '{"adverb":"casually"}', NULL, 2, 493, NULL),
(494, 'catalog', '/ˈkætəlɒɡ/', 'noun', '{"zh-TW":["目錄；型錄"],"en":["a complete list of items arranged systematically"]}', '{"prefix":{"text":"cata-","meaning":"down/complete (完全)"},"root":{"text":"log","meaning":"word/list (字/列表)"},"logic":"完全列出的清單，即「目錄」。"}', 'product catalog / catalog of services', '[{"en":"Please refer to our online product catalog.","zh-TW":"請參閱我們的線上產品目錄。"},{"en":"The catalog lists over 5,000 items.","zh-TW":"目錄列出了5,000多項商品。"}]', NULL, NULL, 3, 494, NULL),
(495, 'catch', '/kætʃ/', 'verb', '{"zh-TW":["【主要意義-動詞】抓住；捕捉","【次要意義-動詞】理解；明白（口語）","【次要意義-動詞】接收到（訊號/廣播）","【次要意義-名詞】隱藏的問題；陷阱；代價"],"en":["[primary] to capture or take hold of something moving","[secondary - verb] to hear and understand something","[secondary - verb] to receive a signal or broadcast","[secondary - noun] a hidden drawback or problem with a seemingly good offer"]}', NULL, 'catch a meeting / catch someone doing / catch on / catch up / the catch is', '[{"en":"Did you catch what the director said about the new restructuring plan?","zh-TW":"你聽清楚主任說的新重組計劃了嗎？"},{"en":"The offer sounds great, but there must be a catch somewhere.","zh-TW":"這個提議聽起來很好，但一定有什麼隱藏的問題。"},{"en":"The new system is beginning to catch on with employees in all departments.","zh-TW":"新系統開始在所有部門的員工中流行起來。"}]', '{"noun":"catch-up, catch-all","adjective":"catching"}', 'catch 作動詞表「理解/聽清楚」（did you catch that?）；名詞 catch = 「隱藏的問題/陷阱」（there is a catch = 有隱藏條件）；catch on（流行起來）均是 TOEIC 閱讀常見陷阱。', 2, 495, NULL),
(496, 'category', '/ˈkætəɡəri/', 'noun', '{"zh-TW":["類別；種類"],"en":["a class or division of people or things"]}', '{"prefix":{"text":"cata-","meaning":"down (完全)"},"root":{"text":"gor","meaning":"speak/accuse (說/指出)"},"suffix":{"text":"-y","meaning":"noun ending (名詞字尾)"},"logic":"指出分類，即「類別」。"}', 'product category / fall into a category', '[{"en":"The products are divided into five main categories.","zh-TW":"產品分為五大類。"},{"en":"This expense falls into the travel category.","zh-TW":"此費用屬於差旅類別。"}]', '{"verb":"categorize","adjective":"categorical"}', NULL, 3, 496, 283),
(497, 'cater', '/ˈkeɪtər/', 'verb', '{"zh-TW":["迎合；提供餐飲服務"],"en":["to provide what is needed or required","to supply food and drink"]}', '{"root":{"text":"cater","meaning":"provide food (提供食物)"},"logic":"提供所需，即「迎合」。"}', 'cater to / cater for / catering service', '[{"en":"Our services cater to small and medium businesses.","zh-TW":"我們的服務迎合中小企業。"},{"en":"The hotel caters for corporate events.","zh-TW":"飯店承辦企業活動。"}]', '{"noun":"catering"}', NULL, 2, 497, NULL),
(498, 'catering', '/ˈkeɪtərɪŋ/', 'noun', '{"zh-TW":["餐飲服務；外燴"],"en":["the business of providing food for events"]}', NULL, 'catering service / event catering', '[{"en":"The hotel''s catering service handled the wedding reception.","zh-TW":"飯店的餐飲服務負責了婚禮接待。"},{"en":"We hired a catering company for the corporate dinner.","zh-TW":"我們為企業晚宴聘請了外燴公司。"}]', '{"verb":"cater","noun":"caterer"}', NULL, 3, 498, NULL),
(499, 'cause', '/kɔːz/', 'noun', '{"zh-TW":["原因；引起"],"en":["the reason something happens","to make something happen"]}', NULL, 'root cause / cause damage', '[{"en":"We need to find the root cause.","zh-TW":"我們需要找出根本原因。"},{"en":"The storm caused major delays.","zh-TW":"暴風雨造成了嚴重的延誤。"}]', '{"noun":"cause","verb":"cause"}', NULL, 2, 499, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(500, 'cautious', '/ˈkɔːʃəs/', 'adjective', '{"zh-TW":["謹慎的；小心的"],"en":["careful to avoid potential problems or dangers"]}', '{"root":{"text":"caut","meaning":"be on guard (警戒)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿警戒的，即「謹慎的」。"}', 'cautious approach / cautious driver', '[{"en":"She is cautious about investing her money.","zh-TW":"她對投資很謹慎。"},{"en":"A cautious approach is recommended.","zh-TW":"建議採取謹慎的做法。"}]', '{"noun":"caution","adverb":"cautiously"}', NULL, 3, 500, 835),
(501, 'cease', '/siːs/', 'verb', '{"zh-TW":["停止；終止","停止"],"en":["to come or bring to an end","to come to an end; to stop"]}', '{"root":{"text":"cess","meaning":"go/yield (走/讓步)"},"logic":"讓步停下來，即「停止」。"}', 'cease operations / cease to exist; cease operations / cease to exist / cease-fire', '[{"en":"The factory will cease operations at the end of the month.","zh-TW":"工廠將在月底停止營運。"},{"en":"The company has ceased trading.","zh-TW":"公司已停止營業。"},{"en":"The factory will cease operations next month.","zh-TW":"工廠下個月將停止運營。"},{"en":"The company ceased to exist after bankruptcy.","zh-TW":"公司破產後就不復存在了。"}]', '{"noun":"cessation","adjective":"ceaseless"}', NULL, 2, 501, NULL),
(502, 'celebrate', '/ˈselɪbreɪt/', 'verb', '{"zh-TW":["慶祝"],"en":["to mark an event with festivities"]}', '{"root":{"text":"celebr","meaning":"honor (尊崇)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使其受到尊崇紀念，即「慶祝」。"}', 'celebrate a birthday / celebrate success', '[{"en":"They celebrated their anniversary with a dinner.","zh-TW":"他們以晚餐慶祝結婚紀念日。"},{"en":"The team celebrated their victory.","zh-TW":"團隊慶祝了他們的勝利。"}]', '{"noun":"celebration"}', NULL, 3, 502, NULL),
(503, 'celebrity', '/sɪˈlɛbrɪti/', 'noun', '{"zh-TW":["名人"],"en":["a famous person"]}', NULL, 'celebrity status / celebrity gossip', '[{"en":"Many celebrities attended the event.","zh-TW":"許多名人出席了活動。"},{"en":"She became a celebrity overnight.","zh-TW":"她一夜成名。"}]', NULL, NULL, 3, 503, NULL),
(504, 'cell', '/sɛl/', 'noun', '{"zh-TW":["細胞；牢房；手機"],"en":["the smallest unit of a living thing"]}', NULL, 'cell phone / prison cell', '[{"en":"Red blood cells carry oxygen.","zh-TW":"紅血球攜帶氧氣。"},{"en":"What''s your cell phone number?","zh-TW":"你的手機號碼是什麼？"}]', NULL, NULL, 1, 504, NULL),
(505, 'census', '/ˈsɛnsəs/', 'noun', '{"zh-TW":["人口普查"],"en":["an official count of the population"]}', NULL, 'national census / census data', '[{"en":"The census is conducted every ten years.","zh-TW":"人口普查每十年進行一次。"},{"en":"Census data shows population growth.","zh-TW":"人口普查數據顯示人口成長。"}]', NULL, NULL, 2, 505, NULL),
(506, 'center', '/ˈsɛntər/', 'noun', '{"zh-TW":["中心；中央"],"en":["the middle point","a building for a particular activity","the middle point of something"]}', NULL, 'shopping center / call center; city center / shopping center', '[{"en":"The call center operates 24 hours.","zh-TW":"客服中心24小時運營。"},{"en":"The city center is very busy.","zh-TW":"市中心非常繁忙。"},{"en":"The hotel is in the city center.","zh-TW":"飯店在市中心。"},{"en":"She is the center of attention.","zh-TW":"她是眾人關注的焦點。"}]', '{"noun":"center","adjective":"central","verb":"centralize","adverb":"centrally"}', NULL, 2, 506, NULL),
(507, 'central', 'ˈsɛntrəl', 'adjective', '{"zh-TW":["中心的；中央的","重要的"],"en":["in the middle","very important"]}', NULL, 'central location/central issue', '[{"en":"This is the central issue we need to address.","zh-TW":"這是我們需要解決的核心問題。"}]', '{"noun":"center","adverb":"centrally"}', NULL, 3, 507, NULL),
(508, 'centralize', '/ˈsentrəlaɪz/', 'verb', '{"zh-TW":["集中化"],"en":["to bring under a single central authority"]}', '{"root":{"text":"centr","meaning":"center (中心)"},"suffix":{"text":"-alize","meaning":"to make (使)"},"logic":"使集中到中心，即「集中化」。"}', 'centralize operations/management/control', '[{"en":"The company centralized all IT operations.","zh-TW":"公司將所有IT營運集中化。"},{"en":"Centralizing procurement can reduce costs.","zh-TW":"集中採購可以降低成本。"}]', '{"noun":"centralization","adjective":"centralized"}', NULL, 4, 508, NULL),
(509, 'CEO', '/ˌsiː iː ˈoʊ/', 'noun', '{"zh-TW":["執行長；首席執行官"],"en":["chief executive officer; the highest-ranking executive in a company"]}', NULL, 'appoint a CEO / role of CEO / CEO succession', '[{"en":"The CEO announced a major restructuring at the annual conference.","zh-TW":"執行長在年度會議上宣布了重大重組。"},{"en":"The new CEO brought a fresh strategic vision to the company.","zh-TW":"新執行長為公司帶來了全新的戰略願景。"}]', '{"full form":"chief executive officer"}', NULL, 1, 509, NULL),
(510, 'ceramic', '/səˈræmɪk/', 'noun', '{"zh-TW":["陶瓷"],"en":["objects made from clay that is heated to high temperatures"]}', '{"root":{"text":"ceram","meaning":"potter''s clay (陶土)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與陶土相關的，即「陶瓷」。"}', 'ceramic tile / ceramic art', '[{"en":"The floor is covered with ceramic tiles.","zh-TW":"地板鋪著瓷磚。"},{"en":"She took a ceramic art class.","zh-TW":"她上了一堂陶藝課。"}]', '{"noun":"ceramics"}', NULL, 3, 510, NULL),
(511, 'certain', '/ˈsɜːrtən/', 'adjective', '{"zh-TW":["確定的；某些"],"en":["sure; having no doubt","specific but not named"]}', NULL, 'for certain / certain conditions', '[{"en":"I am certain the data is correct.","zh-TW":"我確定資料是正確的。"},{"en":"Certain conditions must be met.","zh-TW":"必須滿足某些條件。"}]', '{"adjective":"certain","adverb":"certainly","noun":"certainty"}', NULL, 3, 511, NULL),
(512, 'certificate', '/sərˈtɪfɪkət/', 'noun', '{"zh-TW":["證書；執照","證書；證明"],"en":["an official document attesting a fact","an official document proving something"]}', '{"root":{"text":"cert","meaning":"sure (確定)"},"suffix":{"text":"-ificate","meaning":"thing made (製成品)"},"logic":"使確定的文件，即「證書」。"}', 'certificate of completion / professional certificate; birth certificate / certificate program', '[{"en":"Applicants must provide a certificate of qualification.","zh-TW":"申請者必須提供資格證書。"},{"en":"She earned a professional certificate in project management.","zh-TW":"她取得了專案管理的專業證書。"},{"en":"She received a certificate of completion.","zh-TW":"她收到了結業證書。"},{"en":"You need a birth certificate to apply.","zh-TW":"你需要出生證明才能申請。"}]', '{"verb":"certify","noun":"certification","noun2":"certification"}', NULL, 4, 512, 79),
(513, 'certification', '/ˌsɜːrtɪfɪˈkeɪʃən/', 'noun', '{"zh-TW":["認證；證書"],"en":["official confirmation that someone has met certain standards"]}', NULL, 'professional certification / obtain certification / certification exam', '[{"en":"PMP certification is required for senior project managers.","zh-TW":"PMP認證是高級項目經理的必要條件。"},{"en":"She passed the certification exam on her first attempt.","zh-TW":"她第一次就通過了認證考試。"}]', '{"verb":"certify","adjective":"certified","noun":"certificate"}', NULL, 5, 513, 521),
(514, 'CFO', '/ˌsiː ef ˈoʊ/', 'noun', '{"zh-TW":["財務長；首席財務官"],"en":["chief financial officer; the executive responsible for financial strategy"]}', NULL, 'CFO role / appoint a CFO / CFO responsibilities', '[{"en":"The CFO presented the annual financial results to investors.","zh-TW":"財務長向投資者呈報了年度財務業績。"},{"en":"The CFO oversees budgeting, forecasting, and financial reporting.","zh-TW":"財務長負責監督預算、預測和財務報告。"}]', '{"full form":"chief financial officer"}', NULL, 1, 514, NULL),
(515, 'chain', '/tʃeɪn/', 'noun', '{"zh-TW":["鏈條；連鎖"],"en":["a series of metal rings connected together"]}', NULL, 'food chain / chain reaction', '[{"en":"The dog was on a chain.","zh-TW":"狗被拴在鏈條上。"},{"en":"It''s a popular restaurant chain.","zh-TW":"這是一家受歡迎的連鎖餐廳。"}]', NULL, NULL, 2, 515, NULL),
(516, 'chair', '/tʃɛr/', 'noun', '{"zh-TW":["【主要意義-名詞】椅子","【次要意義-動詞】主持（會議）；擔任主席","【次要意義-名詞】主席；委員會主席職位"],"en":["[primary - noun] a separate seat for one person","[secondary - verb] to act as the chairperson of a meeting or committee","[secondary - noun] the position of chairperson"]}', NULL, 'chair a meeting / chair a committee / take the chair / address the chair', '[{"en":"She was asked to chair the quarterly review meeting.","zh-TW":"她被要求主持季度審查會議。"},{"en":"Who will chair the board meeting in the director''s absence?","zh-TW":"主任缺席時誰來主持董事會會議？"},{"en":"He has chaired the finance committee for three consecutive years.","zh-TW":"他已連續三年擔任財務委員會主席。"}]', '{"noun":"chairperson, chairman, chairwoman, chairmanship"}', '動詞 chair = 「主持會議」，名詞 chair 也可指「主席」職位，是 TOEIC 商務語境中的高頻用法，常出現在會議通知或公告類文章。', 2, 516, NULL),
(517, 'chairman', 'ˈtʃɛrmən', 'noun', '{"zh-TW":["主席；董事長","會長"],"en":["the head of a board","a leader of a meeting"]}', NULL, 'board chairman/chairman of the committee', '[{"en":"The chairman opened the annual meeting.","zh-TW":"主席主持了年度大會。"}]', NULL, NULL, 3, 517, NULL),
(518, 'chairperson', '/ˈtʃɛərˌpɜːrsən/', 'noun', '{"zh-TW":["主席；會議主持人"],"en":["the person leading a meeting or organization"]}', NULL, 'elect a chairperson / acting chairperson', '[{"en":"The chairperson opened the meeting at nine o''clock.","zh-TW":"主席在九點鐘主持開會。"},{"en":"She was elected chairperson of the board.","zh-TW":"她被選為董事會主席。"}]', '{"noun2":"chairman","noun3":"chairwoman"}', NULL, 4, 518, NULL),
(519, 'challenge', '/ˈtʃælɪndʒ/', 'noun', '{"zh-TW":["挑戰；難題"],"en":["a task or situation that tests abilities"]}', '{"root":{"text":"challenge","meaning":"accusation/call to fight (指控/挑戰)"},"logic":"呼叫對抗，即「挑戰」。"}', 'face a challenge / overcome challenges / major challenge', '[{"en":"The biggest challenge is meeting the tight deadline.","zh-TW":"最大的挑戰是趕上緊迫的截止日期。"},{"en":"We must overcome these challenges to succeed.","zh-TW":"我們必須克服這些挑戰才能成功。"}]', '{"adjective":"challenging"}', NULL, 3, 519, 285),
(520, 'challenging', 'ˈtʃælɪndʒɪŋ', 'adjective', '{"zh-TW":["挑戰性的；有難度的","艱鉅的"],"en":["difficult but stimulating","testing your abilities"]}', NULL, 'challenging task/challenging environment', '[{"en":"This is a challenging but rewarding role.","zh-TW":"這是一個具有挑戰性但有意義的職位。"}]', '{"noun":"challenge","adverb":"challengingly"}', NULL, 4, 520, NULL),
(521, 'chamber', '/ˈtʃeɪmbər/', 'noun', '{"zh-TW":["會議廳；商會"],"en":["a large room used for meetings","an enclosed space"]}', '{"root":{"text":"camer","meaning":"room (房間)"},"logic":"房間，即「會議廳」。"}', 'chamber of commerce / chamber music', '[{"en":"The chamber of commerce supports local businesses.","zh-TW":"商會支持當地企業。"},{"en":"The proposal was debated in the upper chamber.","zh-TW":"該提案在上議院進行辯論。"}]', NULL, NULL, 3, 521, NULL),
(522, 'championship', '/ˈtʃæmpiənʃɪp/', 'noun', '{"zh-TW":["錦標賽；冠軍地位"],"en":["a competition to find the best player or team"]}', NULL, 'world championship / win the championship', '[{"en":"They won the national championship.","zh-TW":"他們贏得了全國錦標賽。"},{"en":"The championship game is tomorrow.","zh-TW":"冠軍賽明天舉行。"}]', '{"noun2":"champion"}', NULL, 4, 522, NULL),
(523, 'chance', '/tʃæns/', 'noun', '{"zh-TW":["機會；可能性"],"en":["an opportunity","possibility of something happening","an opportunity; a possibility"]}', NULL, 'by chance / take a chance', '[{"en":"There is a good chance of promotion.","zh-TW":"有很好的升遷機會。"},{"en":"We met by chance at the airport.","zh-TW":"我們在機場巧遇。"},{"en":"Give me one more chance.","zh-TW":"再給我一次機會。"},{"en":"We met by chance at the airport.","zh-TW":"我們在機場偶然相遇。"}]', '{"noun":"chance","adjective":"chance"}', NULL, 2, 523, NULL),
(524, 'change', '/tʃeɪndʒ/', 'verb', '{"zh-TW":["改變；變化","改變；更換"],"en":["to make or become different","to become different or make something different"]}', NULL, 'make a change / change of plan; change mind / climate change', '[{"en":"We need to change our strategy.","zh-TW":"我們需要改變策略。"},{"en":"There has been a change of plan.","zh-TW":"計畫有了變動。"},{"en":"People can change.","zh-TW":"人是可以改變的。"},{"en":"I need to change my clothes.","zh-TW":"我需要換衣服。"}]', '{"verb":"change","noun":"change","adjective":"changeable"}', NULL, 2, 524, NULL),
(525, 'channel', '/ˈtʃænl/', 'noun', '{"zh-TW":["管道；頻道","途徑"],"en":["a medium for communication or distribution"]}', '{"root":{"text":"canal","meaning":"canal/pipe (運河/管道)"},"logic":"傳送的管道，即「頻道、途徑」。"}', 'distribution channel / sales channel / communication channel', '[{"en":"We use multiple channels to reach our customers.","zh-TW":"我們使用多種管道接觸客戶。"},{"en":"Social media has become an important marketing channel.","zh-TW":"社群媒體已成為重要的行銷管道。"}]', NULL, NULL, 3, 525, NULL),
(526, 'chapter', '/ˈtʃæptər/', 'noun', '{"zh-TW":["章節"],"en":["a main division of a book"]}', NULL, 'new chapter / chapter by chapter', '[{"en":"Read chapter three for homework.","zh-TW":"回家作業請讀第三章。"},{"en":"A new chapter of her life began.","zh-TW":"她人生的新篇章開始了。"}]', NULL, NULL, 3, 526, NULL),
(527, 'character', '/ˈkærɪktər/', 'noun', '{"zh-TW":["角色；性格；字元"],"en":["a person in a story; the qualities of a person"]}', NULL, 'main character / out of character', '[{"en":"Who is your favorite character?","zh-TW":"你最喜歡的角色是誰？"},{"en":"That behavior is out of character for him.","zh-TW":"那種行為不像他。"}]', '{"noun2":"characteristic"}', NULL, 3, 527, NULL),
(528, 'characteristic', '/ˌkærɪktəˈrɪstɪk/', 'noun', '{"zh-TW":["特徵；特性"],"en":["a feature typical of a person or thing"]}', '{"root":{"text":"character","meaning":"mark/stamp (標記)"},"suffix":{"text":"-istic","meaning":"relating to (相關的)"},"logic":"與標記相關的特點，即「特徵」。"}', 'key characteristic / distinctive characteristic', '[{"en":"Patience is one of her best characteristics.","zh-TW":"耐心是她最好的特質之一。"},{"en":"What are the characteristics of this material?","zh-TW":"這種材料的特性是什麼？"}]', '{"verb":"characterize","adverb":"characteristically"}', NULL, 5, 528, NULL),
(529, 'characterize', 'ˈkærɪktəraɪz', 'verb', '{"zh-TW":["描述；表徵","刻畫"],"en":["to describe the qualities of","to define characteristics"]}', NULL, 'characterize a situation/characterize trends', '[{"en":"How would you characterize the market?","zh-TW":"您如何描述這個市場？"}]', '{"noun":"characteristic","adjective":"characteristic","adverb":"characteristically"}', NULL, 4, 529, NULL),
(530, 'charge', '/tʃɑːrdʒ/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】充電；收費","【次要意義-名詞】指控；控罪","【次要意義-動詞】負責；掌管"],"en":["[primary] to power a battery; to ask a price","[secondary - noun] a formal accusation in law","[secondary - verb] to be responsible for; to take control of"]}', '{"root":{"text":"charge","meaning":"load (裝載)"},"logic":"裝載責任或費用，即「收費、負責」。"}', 'in charge of / free of charge / take charge / charge with / press charges', '[{"en":"Who will be in charge of the project while the manager is on leave?","zh-TW":"經理休假期間由誰負責這個專案？"},{"en":"The firm was charged with violating antitrust regulations.","zh-TW":"該公司被控違反反壟斷法規。"},{"en":"Delivery is free of charge for orders exceeding 100 dollars.","zh-TW":"訂單超過100美元即可免費送貨。"}]', '{"noun":"chargeable"}', 'charge 有三個 TOEIC 必考用法：in charge of（負責），free of charge（免費），be charged with（被指控），考生容易只記住「充電/收費」而忽略法律和管理方面的含義。', 2, 530, 286),
(531, 'charge-off', '/ˈtʃɑːrdʒ ɒf/', 'noun', '{"zh-TW":["沖銷；呆帳沖銷"],"en":["the declaration by a creditor that an amount of debt is unlikely to be collected"]}', NULL, 'record a charge-off / charge-off rate', '[{"en":"The bank increased its charge-off rate after rising loan defaults.","zh-TW":"銀行在貸款違約增加後提高了沖銷率。"},{"en":"A charge-off reduces the asset value on the creditor''s balance sheet.","zh-TW":"沖銷降低了債權人資產負債表上的資產價值。"}]', NULL, NULL, 4, 531, NULL),
(532, 'chart', 'tʃɑːrt', 'verb', '{"zh-TW":["繪製圖表；記錄","規劃"],"en":["to make a graph or map","to plan a course"]}', NULL, 'chart progress/chart a course', '[{"en":"Let''s chart the progress on a timeline.","zh-TW":"讓我們用時間軸記錄進度。"}]', '{"noun":"chart","adjective":"charted"}', NULL, 2, 532, NULL),
(533, 'charter', '/ˈtʃɑːrtər/', 'noun', '{"zh-TW":["章程；特許狀"],"en":["a written grant of rights by a government or other authority; also to hire a vehicle"]}', NULL, 'company charter / charter flight / charter a vessel', '[{"en":"The company was founded under a royal charter in 1850.","zh-TW":"公司於1850年在皇家特許狀下成立。"},{"en":"The team chartered a private jet for the urgent overseas trip.","zh-TW":"團隊為緊急海外行程包租了私人飛機。"}]', '{"verb":"charter","adjective":"chartered"}', NULL, 3, 533, 652),
(534, 'chase', '/tʃeɪs/', 'verb', '{"zh-TW":["追趕；追求"],"en":["to run after someone to catch them"]}', NULL, 'chase after / wild goose chase', '[{"en":"The dog chased the cat.","zh-TW":"狗追著貓跑。"},{"en":"Stop chasing your dreams and start building them.","zh-TW":"別再追夢了，開始實現它們吧。"}]', NULL, NULL, 2, 534, NULL),
(535, 'chatbot', '/ˈtʃætbɒt/', 'noun', '{"zh-TW":["聊天機器人"],"en":["a computer program that simulates conversation with users"]}', NULL, 'deploy a chatbot / AI chatbot / customer service chatbot', '[{"en":"The chatbot handles 60% of customer inquiries automatically.","zh-TW":"聊天機器人自動處理60%的客戶詢問。"},{"en":"An AI chatbot was implemented to reduce call center volume.","zh-TW":"部署了AI聊天機器人以減少呼叫中心的工作量。"}]', NULL, NULL, 3, 535, NULL),
(536, 'cheap', '/tʃiːp/', 'adjective', '{"zh-TW":["便宜的"],"en":["low in price; not expensive","costing little money"]}', NULL, 'cheap price / cheap labor; dirt cheap / cheap shot', '[{"en":"We found a cheaper supplier.","zh-TW":"我們找到了更便宜的供應商。"},{"en":"Cheap labor attracts manufacturers.","zh-TW":"廉價勞工吸引了製造商。"},{"en":"This bag was really cheap.","zh-TW":"這個包很便宜。"},{"en":"Flying is cheaper than taking the train.","zh-TW":"搭飛機比搭火車便宜。"}]', '{"adjective":"cheap","adverb":"cheaply","verb":"cheapen"}', NULL, 2, 536, NULL),
(537, 'check', '/tʃɛk/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】檢查；核查","【次要意義-名詞】（美式）支票","【次要意義-名詞】制衡；阻止","【次要意義-動詞】核對；加以限制"],"en":["[primary] to examine or verify something","[secondary - noun (AmE)] a written order to a bank to pay money","[secondary - noun] a means of controlling or restraining","[secondary - verb] to restrain or stop something"]}', NULL, 'check in / check out / check against / checks and balances / rain check', '[{"en":"The system of checks and balances prevents any single department from gaining too much power.","zh-TW":"制衡制度防止任何單一部門獲得過多權力。"},{"en":"Please check your figures against the spreadsheet before submitting.","zh-TW":"提交前請對照電子表格核查您的數字。"},{"en":"Can I take a rain check on lunch? I have a meeting at noon.","zh-TW":"午餐可以改天嗎？我中午有個會議。"}]', '{"noun":"checkbox, checkup"}', 'check 有多個次要意義：checks and balances（制衡）、rain check（改期）、check against（核對）均為 TOEIC 高頻表達，美式英語中 check 也指「支票」。', 2, 537, NULL),
(538, 'check-in', '/ˈtʃɛkɪn/', 'noun', '{"zh-TW":["報到；辦理登機手續"],"en":["the process of registering arrival at a hotel or airport"]}', NULL, 'online check-in / check-in counter', '[{"en":"Online check-in opens 24 hours before departure.","zh-TW":"線上報到在出發前24小時開放。"},{"en":"Please proceed to the check-in counter with your passport.","zh-TW":"請攜帶護照前往報到櫃台。"}]', '{"verb":"check in"}', NULL, 3, 538, NULL),
(539, 'check-out', '/ˈtʃɛkaʊt/', 'noun', '{"zh-TW":["退房；結帳"],"en":["the process of leaving a hotel and paying the bill"]}', NULL, 'check-out time / express check-out', '[{"en":"Check-out time is at noon.","zh-TW":"退房時間是中午。"},{"en":"You can use express check-out to save time.","zh-TW":"您可以使用快速退房節省時間。"}]', '{"verb":"check out"}', NULL, 3, 539, NULL),
(540, 'checkout', '/ˈtʃɛkaʊt/', 'noun', '{"zh-TW":["結帳台；結帳"],"en":["the process or location for paying for goods"]}', NULL, 'go to checkout / online checkout', '[{"en":"Please proceed to the checkout when you are ready.","zh-TW":"準備好後請前往結帳台。"},{"en":"The online checkout process takes less than two minutes.","zh-TW":"線上結帳流程不到兩分鐘。"}]', '{"verb":"check out"}', NULL, 3, 540, NULL),
(541, 'checkup', '/ˈtʃɛkʌp/', 'noun', '{"zh-TW":["健康檢查；體檢"],"en":["a routine medical examination"]}', NULL, 'annual checkup / dental checkup', '[{"en":"He goes for a full checkup every year.","zh-TW":"他每年接受一次全面體檢。"},{"en":"The checkup revealed elevated cholesterol levels.","zh-TW":"體檢發現膽固醇偏高。"}]', NULL, NULL, 3, 541, NULL),
(542, 'cheerful', '/ˈtʃɪrfl/', 'adjective', '{"zh-TW":["愉快的；開朗的"],"en":["happy and positive in feeling or attitude"]}', '{"root":{"text":"cheer","meaning":"face/mood (表情/心情)"},"suffix":{"text":"-ful","meaning":"full of (充滿)"},"logic":"充滿好心情的，即「愉快的」。"}', 'cheerful smile / cheerful personality', '[{"en":"She has a cheerful personality.","zh-TW":"她有開朗的個性。"},{"en":"The room was bright and cheerful.","zh-TW":"房間明亮又令人愉悅。"}]', '{"noun":"cheerfulness","adverb":"cheerfully","verb":"cheer"}', NULL, 3, 542, NULL),
(543, 'cheese', '/tʃiːz/', 'noun', '{"zh-TW":["起司；乳酪"],"en":["a solid food made from milk"]}', NULL, 'cream cheese / cheese cake', '[{"en":"Would you like some cheese?","zh-TW":"你要一些起司嗎？"},{"en":"Say cheese for the photo!","zh-TW":"拍照時說起司！"}]', NULL, NULL, 2, 543, NULL),
(544, 'chef', '/ʃɛf/', 'noun', '{"zh-TW":["廚師；主廚"],"en":["a professional cook in a restaurant or hotel"]}', NULL, 'executive chef / head chef', '[{"en":"The head chef trained in France for five years.","zh-TW":"主廚在法國受訓了五年。"},{"en":"The chef prepared a special tasting menu for the evening.","zh-TW":"主廚為當晚準備了特別試菜菜單。"}]', NULL, NULL, 1, 544, NULL),
(545, 'chest', '/tʃɛst/', 'noun', '{"zh-TW":["胸部；箱子"],"en":["the front part of the body between neck and stomach"]}', NULL, 'chest pain / treasure chest', '[{"en":"He felt a pain in his chest.","zh-TW":"他感到胸口疼痛。"},{"en":"They found a treasure chest.","zh-TW":"他們找到了一個寶箱。"}]', NULL, NULL, 2, 545, NULL),
(546, 'chicken', '/ˈtʃɪkɪn/', 'noun', '{"zh-TW":["雞；雞肉"],"en":["a common farm bird; its meat used as food"]}', NULL, 'fried chicken / chicken out', '[{"en":"I''ll have the grilled chicken.","zh-TW":"我要烤雞。"},{"en":"Don''t chicken out now!","zh-TW":"現在別退縮！"}]', NULL, NULL, 3, 546, NULL),
(547, 'chief', '/tʃiːf/', 'adjective', '{"zh-TW":["主要的；首要的","首長"],"en":["most important","the leader of a group"]}', '{"root":{"text":"chief","meaning":"head (頭)"},"logic":"頭部的，即「主要的」。"}', 'chief executive / chief concern / chief officer', '[{"en":"The chief executive addressed the shareholders.","zh-TW":"執行長向股東們致辭。"},{"en":"Cost reduction is our chief concern right now.","zh-TW":"降低成本是我們目前的首要關注。"}]', '{"adverb":"chiefly"}', NULL, 2, 547, NULL),
(548, 'chip', '/tʃɪp/', 'noun', '{"zh-TW":["晶片；薯片"],"en":["a tiny piece of silicon with electronic circuits"]}', NULL, 'computer chip / chip shortage', '[{"en":"The new chip is much faster.","zh-TW":"新晶片快得多。"},{"en":"There''s a global chip shortage.","zh-TW":"全球有晶片短缺的問題。"}]', NULL, NULL, 1, 548, NULL),
(549, 'choice', 'tʃɔɪs', 'noun', '{"zh-TW":["選擇；選項","品質"],"en":["the act of choosing","something chosen"]}', NULL, 'make a choice/wide choice', '[{"en":"You have a choice of three packages.","zh-TW":"您可以選擇三個套餐之一。"}]', '{"verb":"choose","adjective":"choosy"}', NULL, 2, 549, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(550, 'choir', '/kwaɪər/', 'noun', '{"zh-TW":["合唱團"],"en":["a group of people who sing together"]}', '{"root":{"text":"choir","meaning":"chorus (合唱)"},"logic":"源自拉丁語 chorus（合唱），指一群人一起歌唱。"}', 'church choir / join the choir', '[{"en":"She sings in the school choir.","zh-TW":"她在學校合唱團唱歌。"},{"en":"The choir performed at the concert hall.","zh-TW":"合唱團在音樂廳演出。"}]', NULL, NULL, 2, 550, NULL),
(551, 'choose', '/tʃuːz/', 'verb', '{"zh-TW":["選擇"],"en":["to pick from a number of options","to pick one from several options"]}', NULL, 'choose between / choose wisely', '[{"en":"You can choose any color you like.","zh-TW":"你可以選擇任何你喜歡的顏色。"},{"en":"They chose her as team leader.","zh-TW":"他們選她當組長。"},{"en":"You can choose any color.","zh-TW":"你可以選擇任何顏色。"},{"en":"Choose your words carefully.","zh-TW":"謹慎選擇你的用詞。"}]', '{"verb":"choose","noun":"choice","adjective":"chosen"}', NULL, 2, 551, NULL),
(552, 'church', '/tʃɜːrtʃ/', 'noun', '{"zh-TW":["教堂"],"en":["a building for Christian worship"]}', NULL, 'go to church / church service', '[{"en":"They go to church every Sunday.","zh-TW":"他們每個星期天去教堂。"},{"en":"The church was built in 1800.","zh-TW":"這座教堂建於1800年。"}]', NULL, NULL, 2, 552, NULL),
(553, 'circle', '/ˈsɜːrkəl/', 'noun', '{"zh-TW":["圓；圈子"],"en":["a round shape; a group of people"]}', NULL, 'full circle / inner circle', '[{"en":"Draw a circle on the paper.","zh-TW":"在紙上畫一個圓。"},{"en":"She has a wide circle of friends.","zh-TW":"她交友廣泛。"}]', '{"adjective":"circular"}', NULL, 2, 553, NULL),
(554, 'circuit', '/ˈsɜːrkɪt/', 'noun', '{"zh-TW":["電路；巡迴"],"en":["a roughly circular path or journey","an established route for events"]}', '{"root":{"text":"circ","meaning":"circle (圓)"},"suffix":{"text":"-uit","meaning":"going (去)"},"logic":"繞圈走，即「巡迴、電路」。"}', 'circuit board / short circuit / conference circuit', '[{"en":"A short circuit caused the power outage.","zh-TW":"短路導致了停電。"},{"en":"She''s well known on the conference circuit.","zh-TW":"她在會議巡迴圈中頗有名氣。"}]', NULL, NULL, 3, 554, NULL),
(555, 'circular', '/ˈsɜːrkjələr/', 'noun', '{"zh-TW":["通知；通函"],"en":["an official communication sent to a large number of people"]}', NULL, 'company circular / internal circular / issue a circular', '[{"en":"A circular was sent to all staff regarding the new dress code.","zh-TW":"向所有員工發送了關於新著裝規定的通知。"},{"en":"The board issued a circular announcing the CEO change.","zh-TW":"董事會發出了宣布執行長更替的通函。"}]', '{"adjective":"circular"}', NULL, 3, 555, NULL),
(556, 'circulate', '/ˈsɜːrkjʊleɪt/', 'verb', '{"zh-TW":["流通；散布"],"en":["to move continuously through a system","to pass from place to place"]}', '{"root":{"text":"circ","meaning":"circle (圓)"},"suffix":{"text":"-ulate","meaning":"to make (使)"},"logic":"使繞圈流動，即「流通」。"}', 'circulate a memo/report/document', '[{"en":"Please circulate the meeting minutes to all team members.","zh-TW":"請將會議記錄發送給所有團隊成員。"},{"en":"Rumors began to circulate about the merger.","zh-TW":"有關合併的傳言開始流傳。"}]', '{"noun":"circulation"}', NULL, 3, 556, NULL),
(557, 'circulation', '/ˌsɜːrkjʊˈleɪʃən/', 'noun', '{"zh-TW":["發行量；流通"],"en":["the number of copies of a publication distributed"]}', NULL, 'wide circulation / circulation figure', '[{"en":"The report was sent for wide circulation among stakeholders.","zh-TW":"報告已廣泛發送給利害關係人。"},{"en":"The newsletter has a monthly circulation of 10,000 subscribers.","zh-TW":"電子報每月有10,000名訂閱者。"}]', '{"verb":"circulate","adjective":"circulated"}', NULL, 4, 557, 759),
(558, 'circumstance', '/ˈsɜːrkəmstæns/', 'noun', '{"zh-TW":["情況；環境"],"en":["a fact or condition connected with an event","a condition or fact connected with an event"]}', '{"prefix":{"text":"circum-","meaning":"around (周圍)"},"root":{"text":"stance","meaning":"stand (站立)"},"logic":"站在周圍的事物，即「情況」。"}', 'under the circumstances / in certain circumstances; under the circumstances / financial circumstances', '[{"en":"Under the circumstances, we had no choice but to cancel.","zh-TW":"在這種情況下，我們別無選擇只能取消。"},{"en":"Economic circumstances forced a change in strategy.","zh-TW":"經濟情況迫使策略改變。"},{"en":"Under the circumstances, we had no choice.","zh-TW":"在那種情況下，我們別無選擇。"},{"en":"Their financial circumstances have improved.","zh-TW":"他們的經濟狀況有所改善。"}]', '{"adjective":"circumstantial"}', NULL, 4, 558, 80),
(559, 'cite', '/saɪt/', 'verb', '{"zh-TW":["引用；舉例"],"en":["to quote as evidence or an example"]}', '{"root":{"text":"cit","meaning":"call/summon (召喚)"},"logic":"召喚證據，即「引用」。"}', 'cite a source/example/reason', '[{"en":"The report cites several studies as evidence.","zh-TW":"報告引用了多項研究作為證據。"},{"en":"She cited budget constraints as the main reason.","zh-TW":"她以預算限制作為主要原因。"}]', '{"noun":"citation"}', NULL, 1, 559, 653),
(560, 'citizen', '/ˈsɪtɪzən/', 'noun', '{"zh-TW":["公民；市民"],"en":["a person who belongs to a country"]}', NULL, 'senior citizen / citizen rights', '[{"en":"She became a citizen last year.","zh-TW":"她去年成為了公民。"},{"en":"Every citizen has the right to vote.","zh-TW":"每位公民都有投票權。"}]', '{"noun2":"citizenship"}', NULL, 3, 560, NULL),
(561, 'city', '/ˈsɪti/', 'noun', '{"zh-TW":["城市"],"en":["a large town"]}', NULL, 'city center / city council', '[{"en":"The company is based in the city.","zh-TW":"公司設在城市裡。"},{"en":"The city council approved the project.","zh-TW":"市議會批准了這個專案。"}]', '{"noun":"city","adjective":"civic"}', NULL, 1, 561, NULL),
(562, 'claim', '/kleɪm/', 'verb', '{"zh-TW":["聲稱；索賠"],"en":["to state something as fact","to request something as one''s right","to say something is true; to ask for money"]}', '{"root":{"text":"claim","meaning":"cry out (喊出)"},"logic":"大聲喊出主張，即「聲稱」。"}', 'claim responsibility / insurance claim / claim that; claim that / insurance claim', '[{"en":"The company claims its product is the most efficient.","zh-TW":"公司聲稱其產品最有效率。"},{"en":"She filed an insurance claim for the damaged goods.","zh-TW":"她為受損商品提出了保險索賠。"},{"en":"He claims to be an expert.","zh-TW":"他聲稱自己是專家。"},{"en":"She filed an insurance claim.","zh-TW":"她提出了保險索賠。"}]', '{"noun":"claimant"}', NULL, 2, 562, NULL),
(563, 'clarification', 'ˌklærɪfɪˈkeɪʃən', 'noun', '{"zh-TW":["澄清；說明","闡明"],"en":["the act of making something clear","an explanation"]}', NULL, 'request clarification/seek clarification', '[{"en":"Please provide clarification on this point.","zh-TW":"請就此點提供澄清。"}]', '{"verb":"clarify","adjective":"clarified"}', NULL, 5, 563, 522),
(564, 'clarify', '/ˈklærɪfaɪ/', 'verb', '{"zh-TW":["澄清；闡明"],"en":["to make something less confusing and more clear"]}', '{"root":{"text":"clar","meaning":"clear (清楚)"},"suffix":{"text":"-ify","meaning":"to make (使)"},"logic":"使清楚，即「澄清」。"}', 'clarify a point/issue/position', '[{"en":"Could you clarify what you mean by that statement?","zh-TW":"你能澄清那句話的意思嗎？"},{"en":"The spokesperson clarified the company''s position.","zh-TW":"發言人澄清了公司的立場。"}]', '{"noun":"clarification"}', NULL, 3, 564, 287),
(565, 'class', '/klæs/', 'noun', '{"zh-TW":["班級；課程；階級"],"en":["a group of students; a lesson"]}', NULL, 'class room / first class', '[{"en":"I have English class at 10.","zh-TW":"我10點有英文課。"},{"en":"She graduated top of her class.","zh-TW":"她以班上第一名的成績畢業。"}]', '{"adjective":"classic","noun2":"classroom"}', NULL, 2, 565, NULL),
(566, 'classic', '/ˈklæsɪk/', 'adjective', '{"zh-TW":["經典的"],"en":["judged over time to be of the highest quality"]}', '{"root":{"text":"class","meaning":"class/rank (等級)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"屬於最高等級的，即「經典的」。"}', 'classic novel / classic design / a classic example', '[{"en":"This is a classic example of Art Deco architecture.","zh-TW":"這是裝飾藝術建築的經典範例。"},{"en":"She loves reading classic literature.","zh-TW":"她喜歡閱讀經典文學。"}]', '{"noun":"classic","adjective":"classical"}', NULL, 3, 566, NULL),
(567, 'classify', '/ˈklæsɪfaɪ/', 'verb', '{"zh-TW":["分類；歸類"],"en":["to arrange in categories or groups"]}', '{"root":{"text":"class","meaning":"class/group (類別)"},"suffix":{"text":"-ify","meaning":"to make (使)"},"logic":"使成為類別，即「分類」。"}', 'classify information/data/documents', '[{"en":"Products are classified by type and price range.","zh-TW":"產品按類型和價格範圍分類。"},{"en":"The documents were classified as confidential.","zh-TW":"文件被歸類為機密。"}]', '{"noun":"classification"}', NULL, 3, 567, 288),
(568, 'classroom', '/ˈklæsruːm/', 'noun', '{"zh-TW":["教室"],"en":["a room where classes are taught"]}', NULL, 'in the classroom / classroom management', '[{"en":"The classroom was full of students.","zh-TW":"教室裡滿是學生。"},{"en":"Good classroom management is essential.","zh-TW":"良好的課堂管理很重要。"}]', NULL, NULL, 3, 568, NULL),
(569, 'clause', '/klɔːz/', 'noun', '{"zh-TW":["條款；子句"],"en":["a particular section of a legal document","a section of a legal document"]}', '{"root":{"text":"claus","meaning":"close (關閉)"},"logic":"關閉（完結）一個段落，即「條款」。"}', 'contract clause / penalty clause / escape clause; escape clause / confidentiality clause', '[{"en":"The penalty clause specifies damages for late delivery.","zh-TW":"罰款條款規定了延遲交付的賠償金。"},{"en":"Review all clauses carefully before signing.","zh-TW":"簽名前請仔細審閱所有條款。"},{"en":"Read every clause before signing.","zh-TW":"簽名前請閱讀每一條款。"},{"en":"The contract includes a termination clause.","zh-TW":"合同包含終止條款。"}]', NULL, NULL, 2, 569, NULL),
(570, 'clean', '/kliːn/', 'adjective', '{"zh-TW":["乾淨的；清潔","乾淨的"],"en":["free from dirt","to remove dirt"]}', NULL, 'clean energy / clean up; clean up / come clean', '[{"en":"We promote clean energy solutions.","zh-TW":"我們推廣潔淨能源方案。"},{"en":"Please clean up after the meeting.","zh-TW":"會議後請清理乾淨。"},{"en":"Keep your room clean.","zh-TW":"保持你的房間整潔。"},{"en":"He came clean about the mistake.","zh-TW":"他坦白了那個錯誤。"}]', '{"adjective":"clean","verb":"clean","noun":"cleaner","noun2":"cleanliness"}', NULL, 2, 570, NULL),
(571, 'clear', '/klɪr/', 'adjective', '{"zh-TW":["清楚的；明確的"],"en":["easy to understand","transparent"]}', NULL, 'make clear / clear instructions', '[{"en":"The instructions are very clear.","zh-TW":"說明非常清楚。"},{"en":"Let me make one thing clear.","zh-TW":"讓我把一件事說清楚。"}]', '{"adjective":"clear","verb":"clear","adverb":"clearly","noun":"clarity"}', NULL, 2, 571, NULL),
(572, 'clearance', '/ˈklɪrəns/', 'noun', '{"zh-TW":["清倉；許可"],"en":["a sale to clear old stock","official permission"]}', '{"root":{"text":"clear","meaning":"clear (清除)"},"suffix":{"text":"-ance","meaning":"state of (狀態)"},"logic":"清除的狀態，指清倉或獲得許可。"}', 'clearance sale / security clearance', '[{"en":"The store is having a clearance sale this weekend.","zh-TW":"這家店本週末舉辦清倉特賣。"},{"en":"You need security clearance to enter.","zh-TW":"你需要安全許可才能進入。"}]', '{"verb":"clear","adjective":"clear"}', NULL, 3, 572, NULL),
