(575, 'client', '/ˈklaɪənt/', 'noun', '{"zh-TW":["客戶"],"en":["a person or organization using professional services"]}', '{"root":{"text":"cli","meaning":"lean/depend (依靠)"},"suffix":{"text":"-ent","meaning":"person (人)"},"logic":"依靠服務的人，即「客戶」。"}', 'client base / client relationship / potential client', '[{"en":"We aim to build long-term relationships with our clients.","zh-TW":"我們旨在與客戶建立長期關係。"},{"en":"The firm serves over 200 corporate clients.","zh-TW":"該公司服務超過200家企業客戶。"}]', '{"noun":"clientele"}', NULL, 2, 575, 289),
(576, 'clientele', '/ˌkliːɒnˈtɛl/', 'noun', '{"zh-TW":["客戶群"],"en":["all the clients of a business"]}', NULL, 'loyal clientele / build a clientele', '[{"en":"We have a loyal clientele.","zh-TW":"我們有一群忠實的客戶。"},{"en":"The spa attracts a high-end clientele.","zh-TW":"這間SPA吸引高端客群。"}]', '{"noun":"clientele"}', NULL, 3, 576, 760),
(577, 'climate', '/ˈklaɪmɪt/', 'noun', '{"zh-TW":["氣候"],"en":["the usual weather conditions in an area"]}', '{"root":{"text":"clima","meaning":"slope/region (地帶)"},"logic":"源自希臘語 klima（傾斜），指不同地帶的天氣型態。"}', 'climate change / tropical climate', '[{"en":"Climate change is a global concern.","zh-TW":"氣候變遷是全球關注的議題。"},{"en":"This region has a mild climate.","zh-TW":"這個地區氣候溫和。"}]', '{"adjective":"climatic"}', NULL, 3, 577, NULL),
