(581, 'close', '/kloʊz/', 'verb', '{"zh-TW":["【主要意義-動詞/形容詞】關閉；近的","【次要意義-形容詞】悶熱的；通風不良的","【次要意義-形容詞】吝嗇的；小氣的","【次要意義-名詞】結尾；終結"],"en":["[primary] to shut; near in distance or relationship","[secondary - adjective] uncomfortably warm and lacking fresh air","[secondary - adjective] unwilling to spend money; stingy","[secondary - noun] the end or conclusion of something"]}', NULL, 'close call / a close shave / close-fisted / at the close of', '[{"en":"It was close in the meeting room with all the windows shut.","zh-TW":"所有窗戶都關著，會議室裡悶熱難受。"},{"en":"At the close of trading, the index had risen by 2%.","zh-TW":"交易結束時，指數上漲了2%。"},{"en":"The vote was extremely close, with only three votes separating the candidates.","zh-TW":"投票結果極為接近，兩位候選人僅差三票。"}]', '{"noun":"closure","adjective":"closely"}', 'close 作形容詞表「悶熱的」（天氣），名詞 close 表「結尾/收盤」（at the close of business），是 TOEIC 商業新聞和天氣描述中容易混淆的用法。', 2, 581, NULL),
(582, 'closeout', '/ˈkloʊzaʊt/', 'noun', '{"zh-TW":["項目收尾；結案"],"en":["the formal completion and documentation of a project"]}', NULL, 'project closeout / closeout report / closeout meeting', '[{"en":"The closeout report summarized key achievements and lessons learned.","zh-TW":"結案報告總結了主要成就和經驗教訓。"},{"en":"A formal closeout meeting was held with all project stakeholders.","zh-TW":"與所有項目利益相關者舉行了正式結案會議。"}]', '{"verb":"close out"}', NULL, 3, 582, NULL),
(583, 'closing', '/ˈkloʊzɪŋ/', 'noun', '{"zh-TW":["結案；成交；交割"],"en":["the final step in completing a business transaction or property sale"]}', NULL, 'deal closing / closing date / closing documents / closing costs', '[{"en":"The closing of the acquisition was completed last week.","zh-TW":"收購的交割於上週完成。"},{"en":"Closing costs for the property included legal fees and stamp duty.","zh-TW":"房產的交割費用包括法律費用和印花稅。"}]', '{"verb":"close","adjective":"closed"}', NULL, 3, 583, NULL),
